// Today's Mission (specs/missions.md): the daily task played in the app, with a measured score.
// The content lives on GitHub Pages (docs/missions/<level>.js); MISSION_INDEX (MissionIndex.js, generated by
// tools/missions-index.js) tells the server which catalog topics have a mission and how many questions it has.

var MISSION = { minSeconds: 30, flagsPerDay: 20 };

// Settings.MissionPilot: names (comma separated) or "all". Everybody else keeps the link to test-english.com.
function missionsOn(kid) {
  var list = String(getSetting('MissionPilot') || '').toLowerCase().split(',').map(function (s) { return s.trim(); });
  return list.indexOf('all') >= 0 || list.indexOf(String(kid.Name).toLowerCase()) >= 0;
}

function missionOf(url) {
  var idx = typeof MISSION_INDEX === 'object' ? MISSION_INDEX : {};
  return idx.hasOwnProperty(url) ? idx[url] : null;
}

// What the app needs to open a day's mission, or null (no mission for that topic, or the kid is not in the pilot).
function missionView(kid, a, on) {
  if (!a || !on) return null;
  var m = missionOf(a.url);
  return m ? { id: m.id, n: m.n } : null;
}

// One finished mission. The app measures the score; the server checks that it fits the day's mission.
// missed / right: question ids (x:<mission>:<n>) for the spaced review. seconds: time spent playing.
function apiMissionResult(name, pin, date, missionId, correct, total, missed, right, seconds) {
  var kid = auth(name, pin);
  var t = today();
  if (pendingLevelTest(kid)) throw new Error('Take the level test first.');
  if (!missionsOn(kid)) throw new Error('Missions are not open for you yet.');
  if (weekDates(t).indexOf(date) < 0 || date > t || date < kidStart(kid)) throw new Error('You can only log tasks from this week.');
  var a = ensureAssignments(kid, [date])[date];
  var m = a && missionOf(a.url);
  if (!m || m.id !== String(missionId)) throw new Error('This mission is not the one for that day. Refresh and try again.');
  correct = Math.round(Number(correct));
  total = Math.round(Number(total));
  seconds = Math.round(Number(seconds)) || 0;
  if (!(total === m.n && correct >= 0 && correct <= total)) throw new Error('Invalid score');
  if (seconds < MISSION.minSeconds) throw new Error('That was too quick to count. Play the mission to the end.');
  var prefix = 'x:' + m.id + ':';
  var mine = function (id) { return id.indexOf(prefix) === 0; };
  missed = cleanIds(missed, total).filter(mine);
  right = cleanIds(right, total).filter(mine);
  var entry;
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var done = readTableUncached('Log').filter(function (l) { return l.Girl === kid.Name && l.Date === date; });
    if (done.length) throw new Error('This task is already marked as done.');
    var pct = Math.round(correct / total * 100);
    var points = 10 + (pct >= 80 ? 5 : 0) + (date === t ? 3 : 0);
    entry = {
      Timestamp: new Date(), Girl: kid.Name, Date: date, DoneOn: t, Section: a.section, Level: a.level, Title: a.title, URL: a.url,
      Correct: correct, Total: total, Percent: pct, Points: points, Mission: m.id, Seconds: Math.min(seconds, 3600)
    };
    appendRow('Log', entry);
    updateReview(kid.Name, missed, right, t);
  } finally {
    lock.releaseLock();
  }
  try { notifyCompletion(kid, entry); } catch (e) { console.error(e); }
  try { duoAfterPractice(kid.Name); } catch (e) { console.error(e); }
  var dash = buildDashboard(findGirl(kid.Name));
  dash.justEarned = dash.week.filter(function (d) { return d.date === date; })[0].points;
  return dash;
}

// "Something wrong here?" under a question: kept in the Flags tab for the owner to check.
function apiFlag(name, pin, missionId, itemId, note) {
  var kid = auth(name, pin);
  var t = today();
  missionId = String(missionId || '').replace(/[^A-Za-z0-9]/g, '').slice(0, 12);
  itemId = cleanIds([itemId], 1)[0] || '';
  note = String(note || '').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim().slice(0, 300);
  if (!missionId) throw new Error('Unknown mission');
  var mine = readTable('Flags').filter(function (f) { return f.Girl === kid.Name && f.Date === t; });
  if (mine.length >= MISSION.flagsPerDay) return { ok: true };
  appendRow('Flags', { Timestamp: new Date(), Girl: kid.Name, Date: t, Mission: missionId, Item: itemId, Note: note });
  return { ok: true };
}
